export function patchOrder(id: string, body: PatchOrderBody, signal?: AbortSignal) {
  return apiFetch<OrderDetail>(`/api/orders/${encodeURIComponent(id)}`, {
    method: "PATCH",
    body,
    signal,
  });
}

